import React, { useEffect, useMemo, useState } from "react";
import type { RoomTimeSlot } from "../../../api";
import { groupSlotsByComment, type SlotGroupItem } from "./banyaSlotVariants";
import { estimateSlotPriceBeforeDiscount } from "./slotPricing";

function formatTimeEnd(timeTo: string): string {
  if (timeTo === "23:59") return "24:00";
  return timeTo;
}

function formatDuration(hours: number): string {
  const n = Number.isFinite(hours) ? hours : 0;
  return `${n} ч`;
}

function formatRub(value: number): string {
  return new Intl.NumberFormat("ru-RU").format(value);
}

function SlotItemButton({
  slot,
  index,
  selected,
  onSelect,
}: {
  slot: RoomTimeSlot;
  index: number;
  selected: boolean;
  onSelect: (slot: RoomTimeSlot, index: number) => void;
}) {
  const available = slot.isAvailable === true;
  const oldPrice = estimateSlotPriceBeforeDiscount(slot);
  return (
    <button
      type="button"
      className={[
        "booking-slots__item",
        available && "booking-slots__item--free",
        !available && "booking-slots__item--busy",
        available && selected && "booking-slots__item--selected",
      ]
        .filter(Boolean)
        .join(" ")}
      disabled={!available}
      aria-pressed={selected}
      onClick={() => {
        if (!available) return;
        onSelect(slot, index);
      }}
    >
      <span className="booking-slots__item-main">
        <span className="booking-slots__time">
          {slot.timeFrom}&nbsp;–&nbsp;{formatTimeEnd(slot.timeTo)}
        </span>
        <span className="booking-slots__duration">
          {formatDuration(slot.duration)}
        </span>
      </span>
      {slot.price > 0 && oldPrice != null && oldPrice > slot.price ? (
        <span className="booking-slots__price booking-slots__price--promo">
          <s className="booking-slots__price-old">
            <span className="booking-slots__sr">Без скидки </span>
            {formatRub(oldPrice)} ₽
          </s>
          <span className="booking-slots__price-new">
            {formatRub(slot.price)} ₽
          </span>
        </span>
      ) : slot.price > 0 ? (
        <span className="booking-slots__price">{formatRub(slot.price)} ₽</span>
      ) : (
        <span className="booking-slots__price booking-slots__price--empty" />
      )}
    </button>
  );
}

function SlotList({
  items,
  selectedIndex,
  onSelect,
}: {
  items: SlotGroupItem[];
  selectedIndex: number | null;
  onSelect: (slot: RoomTimeSlot, index: number) => void;
}) {
  return (
    <ul className="booking-slots__list">
      {items.map(({ slot, index }) => (
        <li key={`${slot.timeFrom}-${slot.timeTo}-${index}`}>
          <SlotItemButton
            slot={slot}
            index={index}
            selected={selectedIndex === index}
            onSelect={onSelect}
          />
        </li>
      ))}
    </ul>
  );
}

type Props = {
  slots: RoomTimeSlot[];
  isLoading?: boolean;
  hasError?: boolean;
  selectedIndex: number | null;
  onSelect: (slot: RoomTimeSlot, index: number) => void;
  onRetry?: () => void;
};

export const BanyaTimeSlots: React.FC<Props> = ({
  slots,
  isLoading = false,
  hasError = false,
  selectedIndex,
  onSelect,
  onRetry,
}) => {
  const [showAll, setShowAll] = useState(false);
  const freeItems = useMemo(
    () =>
      slots
        .map((slot, index) => ({ slot, index }))
        .filter((item) => item.slot.isAvailable === true),
    [slots]
  );
  const previewItems = freeItems.slice(0, 4);
  const hasMore =
    freeItems.length > previewItems.length ||
    slots.some((slot) => slot.isAvailable !== true);
  const groups = useMemo(() => groupSlotsByComment(slots), [slots]);

  const slotsKey = useMemo(
    () => slots.map((s) => `${s.timeFrom}-${s.timeTo}-${s.comment}`).join("|"),
    [slots]
  );
  useEffect(() => {
    setShowAll(false);
  }, [slotsKey]);

  if (isLoading) {
    return (
      <div
        className="booking-slots__state booking-slots__state--loading"
        role="status"
        aria-live="polite"
        aria-busy="true"
      >
        <div className="booking-slots__spinner" aria-hidden />
        <p className="booking-slots__state-title">Загрузка слотов</p>
        <p className="booking-slots__state-detail">
          Подбираем свободное время на выбранную дату
        </p>
        <ul className="booking-slots__skeleton" aria-hidden>
          <li className="booking-slots__skeleton-item" />
          <li className="booking-slots__skeleton-item" />
          <li className="booking-slots__skeleton-item" />
        </ul>
      </div>
    );
  }

  if (hasError) {
    return (
      <div
        className="booking-slots__state booking-slots__state--error"
        role="alert"
      >
        <p className="booking-slots__state-title">
          Не удалось загрузить слоты
        </p>
        <p className="booking-slots__state-detail">
          Проверьте соединение и попробуйте ещё раз
        </p>
        {onRetry ? (
          <button
            type="button"
            className="booking-slots__retry"
            onClick={onRetry}
          >
            Повторить
          </button>
        ) : null}
      </div>
    );
  }

  if (slots.length === 0 || previewItems.length === 0) {
    return (
      <div className="booking-slots__state" role="status">
        <p className="booking-slots__state-title">Нет свободных слотов</p>
      </div>
    );
  }

  return (
    <div className="booking-slots__groups" aria-label="Слоты времени">
      {showAll ? (
        groups.map((group, groupIndex) => (
          <section
            key={`${group.title}-${groupIndex}`}
            className="booking-slots__group booking-slots__group--static"
          >
            {group.title ? (
              <h5 className="booking-slots__group-title">{group.title}</h5>
            ) : null}
            <SlotList
              items={group.items}
              selectedIndex={selectedIndex}
              onSelect={onSelect}
            />
          </section>
        ))
      ) : (
        <>
          <SlotList
            items={previewItems}
            selectedIndex={selectedIndex}
            onSelect={onSelect}
          />
          {hasMore ? (
            <button
              type="button"
              className="booking-slots__more"
              onClick={() => setShowAll(true)}
            >
              Показать все слоты
            </button>
          ) : null}
        </>
      )}
    </div>
  );
};

// Re-export for existing tests / callers
export { groupSlotsByComment } from "./banyaSlotVariants";
